export const seedPosts: Post[] = [];

export const seedReviews: Review[] = [];

export function toPublicMarket(m: SeedMarket): Market {
  const stats = marketReviewStats[m.slug];
  return {
    id: m.id,
    slug: m.slug,
    name: m.name,
    about: m.about,
    address: m.address,
    city: m.city,
    province: m.province,
    postal_code: m.postal_code,
    lat: m.lat,
    lng: m.lng,
    geofence_radius_m: m.geofence_radius_m,
    website: m.website,
    instagram: m.instagram ?? null,
    tiktok: m.tiktok ?? null,
    phone: m.phone,
    email: m.email ?? null,
    logo_url: m.logo_url ?? null,
    tags: m.tags,
    status: "published",
    featured: m.featured,
    review_count: m.review_count ?? stats?.review_count ?? 0,
    rating_avg: m.rating_avg ?? stats?.rating_avg ?? null,
    claimed_by: null,
  };
}

export function schedulesFor(marketId: string): MarketSchedule[] {
  const m = seedMarkets.find((x) => x.id === marketId);
  if (!m) return [];
  return m.schedules.map((s, i) => ({
    id: `${marketId}-sch-${i}`,
    market_id: marketId,
    ...s,
  }));
}

export function toPublicVendor(v: SeedVendor): Vendor {
  const stats = vendorReviewStats[v.slug];
  return {
    id: v.id,
    slug: v.slug,
    name: v.name,
    about: v.about,
    website: v.website,
    instagram: v.instagram ?? null,
    tiktok: v.tiktok ?? null,
    phone: v.phone,
    logo_url: v.logo_url ?? null,
    tags: v.tags,
    status: "published",
    review_count: v.review_count ?? stats?.review_count ?? 0,
    rating_avg: v.rating_avg ?? stats?.rating_avg ?? null,
    claimed_by: null,
  };
}

export function menusFor(vendorId: string): MenuItem[] {
  const v = seedVendors.find((x) => x.id === vendorId);
  if (!v) return [];
  return v.menus.map((item, i) => ({
    id: `${vendorId}-menu-${i}`,
    vendor_id: vendorId,
    ...item,
  }));
}
